  'help.type.security': 'Sikkerhed',
  'help.type.other': 'Andet',
  'help.faq.cantLogin.q': 'Jeg kan ikke logge ind på min konto',
  'help.faq.cantLogin.a': 'Sørg for, at du bruger den rigtige email og adgangskode. Hvis du har glemt din adgangskode, klik på "Glemt adgangskode?" på login-skærmen. Hvis problemet fortsætter, opret en supportbillet.',
  'help.faq.notReceiving.q': 'Jeg modtager ikke emails',
  'help.faq.notReceiving.a': 'Tjek først din Spam-mappe. Sørg for, at din opbevaring ikke er fuld. Hvis problemet fortsætter, bekræft at afsenderen har den rigtige emailadresse og opret en supportbillet.',
  'help.faq.cantSend.q': 'Jeg kan ikke sende emails',
  'help.faq.cantSend.a': 'Bekræft din internetforbindelse og at modtagerens emailadresse er korrekt. Tjek om du har vedhæftninger, der er for store (max 25MB). Prøv igen om et par minutter.',
  'help.faq.forgotPassword.q': 'Jeg har glemt min adgangskode',
  'help.faq.forgotPassword.a': 'På login-skærmen, klik på "Glemt adgangskode?" og følg instruktionerne for at nulstille din adgangskode via din gendannelses-emailadresse.',
  'help.faq.accountSecurity.q': 'Jeg tror, min konto er blevet kompromitteret',
  'help.faq.accountSecurity.a': 'Skift straks din adgangskode. Tjek din Sendt-mappe for beskeder, du ikke har sendt. Aktivér to-faktor autentificering i Indstillinger > Sikkerhed. Hvis nødvendigt, opret en hastesupportbillet.',
  'help.faq.appAccess.q': 'Hvordan får jeg adgang til appen på mobilen?',
  'help.faq.appAccess.a': 'Du kan få adgang til Chatyy via enhver mobilbrowser på chatyy.com.br, eller download vores app fra din enheds appbutik.',

  // Privacy modal
  'privacy.title': 'Privatlivspolitik',
  'privacy.subtitle': 'Hvordan vi beskytter og håndterer dine data',
  'privacy.lastUpdated': 'Sidst opdateret: Marts 2026',
  'privacy.dataCollection.title': 'Dataindsamling',
  'privacy.dataCollection.body': 'Vi indsamler kun de oplysninger, der er nødvendige for at levere vores emailservice: dit navn, emailadresse og indholdet af beskeder, du sender og modtager. Vi sælger eller deler ikke dine personlige data med tredjeparter til markedsføringsformål.',
  'privacy.dataUsage.title': 'Hvordan Vi Bruger Dine Data',
  'privacy.dataUsage.body': 'Dine data bruges udelukkende til at drive og forbedre emailservicen, herunder levering af beskeder, filtrering af spam, levering af AI-drevne funktioner (med dit samtykke) og opretholdelse af kontosikkerhed.',
  'privacy.dataSecurity.title': 'Datasikkerhed',
  'privacy.dataSecurity.body': 'Vi bruger industristandard kryptering (TLS/SSL) for alle data under transport og i hvile. Sessioner er beskyttet med krypterede tokens og CSRF-beskyttelse. Vi reviderer regelmæssigt vores sikkerhedspraksis.',
  'privacy.cookies.title': 'Cookies & Lokal Opbevaring',
  'privacy.cookies.body': 'Vi bruger essentielle cookies og lokal opbevaring for at opretholde din session, huske dine præferencer (tema, sprog) og give en problemfri oplevelse. Vi bruger ikke tracking-cookies fra tredjeparter.',
  'privacy.thirdParties.title': 'Tredjeparts Tjenester',
  'privacy.thirdParties.body': 'Vi kan bruge tredjeparts tjenester til specifik funktionalitet såsom AI-funktioner (Anthropic Claude) og push-notifikationer. Disse tjenester er underlagt deres egne privatlivspolitikker og behandler kun de minimumsdata, der kræves.',
  'privacy.rights.title': 'Dine Rettigheder',
  'privacy.rights.body': 'Du har ret til at få adgang til, rette, eksportere eller slette dine personlige data når som helst. Du kan administrere dine data gennem Indstillinger eller ved at kontakte vores supportteam.',
  'privacy.contact.title': 'Kontakt Os',
  'privacy.contact.body': 'For spørgsmål vedrørende privatliv eller dataanmodninger, kontakt os på privacy@chatyy.com.br. Vi svarer inden for 30 dage.',

  // Terms modal
  'terms.title': 'Servicevilkår',
  'terms.subtitle': 'Retningslinjer for brug af Chatyy',
  'terms.lastUpdated': 'Sidst opdateret: Marts 2026',
  'terms.acceptance.title': 'Accept af Vilkår',
  'terms.acceptance.body': 'Ved at få adgang til eller bruge Chatyy, accepterer du at være bundet af disse Servicevilkår. Hvis du ikke er enig i nogen del af disse vilkår, må du ikke bruge tjenesten.',
  'terms.services.title': 'Beskrivelse af Tjenester',
  'terms.services.body': 'Chatyy tilbyder emailkommunikationstjenester, herunder sending, modtagelse og håndtering af emails, sammen med AI-drevne funktioner, kalenderintegration og videokonferencekapaciteter.',
  'terms.accounts.title': 'Bruger Konti',
  'terms.accounts.body': 'Du er ansvarlig for at opretholde sikkerheden af dine kontooplysninger. Du må ikke dele din adgangskode eller tillade uautoriseret adgang til din konto. Du skal være mindst 13 år gammel for at bruge denne tjeneste.',
  'terms.conduct.title': 'Acceptabel Brug',
  'terms.conduct.body': 'Du accepterer ikke at bruge tjenesten til at sende spam, malware, phishing eller noget ulovligt indhold. Du må ikke forsøge at få adgang til andre brugeres konti eller forstyrre tjenestens infrastruktur.',
  'terms.content.title': 'Indholdsejerskab',
  'terms.content.body': 'Du bevarer ejerskabet af alt indhold, du opretter og sender gennem tjenesten. Vi gør ikke krav på ejerskab over dine emails eller vedhæftninger. Vi kan behandle indhold som nødvendigt for at levere tjenesten.',
  'terms.limitation.title': 'Begrænsning af Ansvar',
  'terms.limitation.body': 'Chatyy leveres "som den er". Vi stræber efter 99,9% oppetid, men garanterer ikke uafbrudt service. Vi er ikke ansvarlige for indirekte, tilfældige eller følgeskader, der opstår fra din brug af tjenesten.',
  'terms.termination.title': 'Kontoopsigelse',
  'terms.termination.body': 'Vi kan suspendere eller opsige konti, der overtræder disse vilkår. Du kan slette din konto når som helst gennem Indstillinger. Ved opsigelse vil dine data blive slettet inden for 30 dage.',
  'terms.changes.title': 'Ændringer i Vilkår',
  'terms.changes.body': 'Vi kan opdatere disse vilkår fra tid til anden. Vi vil informere dig om væsentlige ændringer via email eller in-app notifikation. Fortsat brug af tjenesten efter ændringer udgør accept af de opdaterede vilkår.',

