  // Offline-first: shown when we tried to load a remote URL but the device is
  // offline AND the file isn't in the local media cache (i.e. user never
  // viewed it while online). Distinct from cacheEvicted (was cached, then
  // dropped by LRU) — this one means "not yet cached, no way to fetch now".
  'media.offlineCacheMiss': 'Ingen internet — dette media er ikke blevet downloadet endnu.',
  // Header for the offline-but-not-cached state (paired with offlineCacheMiss
  // body). Replaces the misleading "Mídia removida do cache" header that fired
  // for every Image onError including transient network failures.
  'media.offlineTitle': 'Ingen internet',
  // Codec-level failure (file IS on disk but the player can't decode — usually
  // Android <10 + .opus, or a 0-byte download). Distinct from offlineCacheMiss
  // because here re-downloading won't fix it; we just tell the user the
  // format is unsupported so they don't think Chatyy is offline.
